Translate("zhCN", "stranglethorn-vale", {
	title = "荆棘谷",
	aliases = { "荆棘之地", "山谷" },
	sections = {
		{
			title = "概述",
			text = [=[荆棘谷是南方的大丛林。它从{link:duskwood}暮色森林{/link}幽暗的边界一直延伸到一处岩石嶙峋的{link:fleet-master-seahorn}海角{/link}，陆地在那里没入大海。这里的树木古老而高大，河中满是鳄鱼，猛虎、黑豹、迅猛龙和猿猴在绿色的林冠下猎食。藤蔓随处吞没了一个没落{link:trolls}巨魔{/link}帝国的石块。这里没有王权统治。地精占据着{link:booty-bay}藏宝海湾{/link}港，{link:horde}部落{/link}在西岸设有一座营地，北方来的猎人和逃兵在山丘间支起帐篷，而巨魔各部族则在祖先的废墟中延续着古老的战争。]=],
		},
		{
			title = "起源",
			text = [=[这里曾是古拉巴什的心脏，古拉巴什是南方的丛林{link:trolls}巨魔{/link}。在{link:great-sundering}大分裂{/link}之前的诸多纪元里，他们的帝国横跨这片土地，并远远延伸到更远的地方。世界破碎之时，帝国的大片土地沉入海中，困境中的子民转向了黑暗的崇拜。阿塔莱的祭司们在他们的都城{link:zul-gurub}祖尔格拉布{/link}召唤出了血神{link:hakkar}哈卡{/link}。这位神灵以他的崇拜者为食，最终各部族起来反抗他和他的祭司。他们将哈卡驱逐出去，并把阿塔莱赶进了北方的{link:swamp-of-sorrows}沼泽{/link}。古拉巴什帝国再也没有恢复元气。它的部族彼此反目，他们建造的城市被留给了丛林。]=],
		},
		{
			title = "当今",
			text = [=[荆棘谷没有主人，因此它有许多主人。{link:steamwheedle-cartel}热砂港{/link}的地精统治着南端的{link:booty-bay}藏宝海湾{/link}，在那里，任何旗帜只要肯付钱都受欢迎。两支敌对船队的海盗，{red:blackwater-raiders}黑水海盗{/red}和{red:bloodsail-buccaneers}血帆海盗{/red}，为争夺{link:fleet-master-seahorn}海角{/link}的水域而战。{link:venture-company}风险投资公司{/link}在北方的山丘上掠夺木材和水晶。在北方，一队来自{link:stormwind-city}暴风城{/link}的士兵正与他们自己从前的上校进行一场绝望的战争。在西岸，{link:horde}部落{/link}建起了{link:grom-gol-base-camp}格罗姆高{/link}，其{link:darkspear-trolls}暗矛{/link}使者回到故土，寻找部族中一个失落的儿子。著名的猎人{link:hemet-nesingwary}赫米特·奈辛瓦里二世{/link}前来猎杀丛林中的巨兽。而在这一切背后，{link:trolls}巨魔{/link}们依然顽强生存：血顶部族、劈颅部族，以及{link:zanzil-the-outcast}流亡者赞吉尔{/link}的追随者，彼此之间仍在交战。]=],
		},
		{
			title = "居民",
			text = [=[• {b}{link:booty-bay}藏宝海湾{/link}的地精。{/b}{link:steamwheedle-port}热砂港{/link}的商人、掮客和打手，以及在他们的酒馆里饮酒的黑水海盗。
• {b}血帆海盗。{/b}登陆{link:wild-shore}蛮荒海岸{/link}、图谋对付这座港口的敌对海盗。
• {b}古拉巴什各部族。{/b}西北废墟中的血顶{link:trolls}巨魔{/link}，中部废墟中的劈颅巨魔，以及{link:fleet-master-seahorn}海角{/link}上{link:zanzil-the-outcast}赞吉尔{/link}的追随者。在{link:zul-gurub}祖尔格拉布{/link}的城墙后面，更古老的力量仍在蠢动。
• {b}反抗军与逃兵。{/b}北方{link:lieutenant-doren}多伦上尉{/link}的反抗军，以及他们东边营地里{link:colonel-kurzen}库尔森上校{/link}的手下。
• {b}{link:grom-gol-base-camp}格罗姆高{/link}的{link:horde}部落{/link}。{/b}{link:orcs}兽人{/link}和{link:darkspear-trolls}暗矛巨魔{/link}，守卫着通往{link:stonard}斯通纳德{/link}的补给线和飞往北方的飞艇。
• {b}猎人们。{/b}{link:hemet-nesingwary}赫米特·奈辛瓦里二世{/link}和他的同伴，扎营于北方的河边。
• {b}{link:ogres}食人魔{/link}。{/b}{link:mosh-ogg-ogre-mound}莫什奥格{/link}氏族占据着东部山区的一座土丘和{link:mizjah-ruins}米扎废墟{/link}。
• {b}{link:naga}纳迦{/link}、{link:murlocs}鱼人{/link}和海中的巨人。{/b}它们出没于海岸、沉没的废墟和{link:the-vile-reef}暗礁{/link}之间。]=],
		},
		{
			title = "历史",
			text = [=[• {b}帝国。{/b}在漫长的岁月里，古拉巴什从{link:zul-gurub}祖尔格拉布{/link}统治着这片丛林。他们的石头城市沿着河流和海岸拔地而起。
• {b}{link:hakkar}夺灵者{/link}。{/b}哈卡被阿塔莱召唤到这个世界。对他的崇拜使帝国陷入内战，而他的失败让帝国四分五裂。
• {b}离散。{/b}古拉巴什各部族为争夺残存之物而相互厮杀。{link:darkspear-trolls}暗矛部族{/link}被逐出丛林，迁往南方海域的岛屿。
• {b}地精。{/b}地精将{link:trolls}巨魔{/link}赶出了丛林南端的一处港湾，并在那里建起了{link:booty-bay}藏宝海湾{/link}。丛林的史书没有记载那一年。
• {b}当今。{/b}北方人越来越多地到来：士兵、猎人、矿工，还有{link:horde}部落{/link}。他们之中没有谁驯服了这片山谷。]=],
		},
		{
			title = "丛林传说",
			text = [=[• 据说，{link:azeroth}艾泽拉斯{/link}的每一个种族都声称，西部悬崖上那眼{link:nek-mani-wellspring}圣泉{/link}的泉水是只为本族而祝圣的恩赐。
• {link:rebel-camp}反抗军营地{/link}的士兵们相互传说，{link:booty-bay}藏宝海湾{/link}的地精会把喝醉的水手拖上奴隶船，带到无人提及的地方去。
• 一种名为荆棘谷热病的疾病在{link:fleet-master-seahorn}海角{/link}上击倒了水手。巫医们说，唯一的解药是一只白色猿猴的心脏，而那只猿猴无人能够找到。
• {link:hemet-nesingwary}赫米特·奈辛瓦里二世{/link}写过一本关于他在丛林中狩猎的书。书页曾被风吹散，据说丛林中至今仍藏着其中几页。]=],
		},
		{
			title = "未载之事",
			text = [=[没有任何史书记载古拉巴什帝国兴起、衰落或离散的年份，也没有记载地精夺取{link:booty-bay}藏宝海湾{/link}的那一年。]=],
		},
	},
})

Translate("zhCN", "booty-bay", {
	title = "藏宝海湾",
	sections = {
		{
			title = "概述",
			text = [=[藏宝海湾是{link:stranglethorn-vale}荆棘谷{/link}南端的地精港口。从丛林进入的道路穿过悬崖中的一条隧道，而城镇本身依附在一处深湾的岩壁上，一圈又一圈的木屋和走道环绕着拥挤的港口。{link:baron-revilgaz}大财主里维加兹{/link}在酒馆的顶层统治着这里。{link:steamwheedle-cartel}热砂港{/link}的打手维持着{link:alliance}联盟{/link}与{link:horde}部落{/link}之间的和平，{red:blackwater-raiders}黑水海盗{/red}的海盗在航行间隙挤满了这里的旅店。船只从它的码头出发，越过大海驶向{link:ratchet}棘齿城{/link}。这里什么都买得到，大多数东西也都卖得出去。]=],
		},
	},
})

Translate("zhCN", "gurubashi-arena", {
	title = "古拉巴什竞技场",
	aliases = { "竞技场" },
	sections = {
		{
			title = "概述",
			text = [=[古拉巴什竞技场是丛林中心的一座巨大石环，由{link:trolls}巨魔{/link}在他们帝国的时代建造。它的看台至今仍然矗立，开裂且长满植物，环绕着一片沙地。巨魔如今已离开了这里。一个名叫{link:short-john-mithril}小个子约翰·米斯瑞尔{/link}的海盗不时会在场地上放下一箱宝藏，让丛林中最大胆的斗士为之互相厮杀。他说，那些一次又一次获胜的人，可以自称竞技场的大师。]=],
		},
	},
})

Translate("zhCN", "zul-gurub", {
	title = "祖尔格拉布",
	sections = {
		{
			title = "概述",
			text = [=[祖尔格拉布曾是古拉巴什{link:trolls}巨魔{/link}的伟大城市，他们的帝国曾从这里统治南方。阿塔莱祭司正是在这里将夺灵者{link:hakkar}哈卡{/link}召唤到这个世界，各部族也正是在这里起来将他推翻。这座城市位于丛林的东北部，藏在藤蔓未能摧毁的城墙之后。它的大门紧闭。古拉巴什战士和哈卡莱祭司仍在门前守望，一位高阶女祭司在他们中间巡行。住在附近的人不去过问城内发生着什么。]=],
		},
		{
			title = "如今",
			text = [=[{link:darkspear-trolls}暗矛{/link}没有忘记这座城市。部族曾按照习俗的要求，将酋长最小的儿子{link:yenniku}耶尼库{/link}交给了祖尔格拉布。如今，{link:vol-jin}沃金{/link}谈到了即将与城中{link:trolls}巨魔{/link}进行的战斗。最近，有人看见一个来自遥远赞达拉部族的巨魔在窥视它的城墙。]=],
		},
	},
})

Translate("zhCN", "nesingwary-s-expedition", {
	title = "奈辛瓦里远征队营地",
	aliases = { "奈辛瓦里的营地", "奈辛瓦里远征队" },
	sections = {
		{
			title = "概述",
			text = [=[奈辛瓦里远征队营地是丛林北部的一座狩猎营地，位于{link:venture-company}风险投资公司{/link}在{link:lake-nazferiti}纳菲瑞提湖{/link}的作业场上游。营地的帐篷围着一堆篝火，狩猎的战利品陈列在露天。{link:dwarves}矮人{/link}{link:hemet-nesingwary}赫米特·奈辛瓦里二世{/link}和他的同伴们聚集在这里，猎杀{link:stranglethorn-vale}荆棘谷{/link}的巨兽：猛虎、黑豹和迅猛龙，而最重要的是一只白虎。猎人们欢迎枪法准的陌生人。对其他人，他们没什么耐心。]=],
		},
	},
})

Translate("zhCN", "rebel-camp", {
	title = "反抗军营地",
	sections = {
		{
			title = "概述",
			text = [=[反抗军营地位于丛林的最北端，靠近从{link:duskwood}暮色森林{/link}下来的道路。这是一圈由帐篷和箱子围成的小栅栏营地，由{link:stormwind-city}暴风城{/link}的士兵据守，他们曾追随{link:colonel-kurzen}库尔森上校{/link}，后来又背叛了他。{link:lieutenant-doren}多伦上尉{/link}指挥着他们。他们人数很少，上校的手下比他们多出许多倍。{link:booty-bay}藏宝海湾{/link}的地精给他们送来补给，其中包括用来守卫营地通道的地{link:farmer-ray}雷{/link}。这里的每个士兵都知道，只要出一个叛徒，就足以让他们全军覆没。]=],
		},
	},
})

Translate("zhCN", "kurzen-s-compound", {
	title = "库尔森的营地",
	aliases = { "库尔森营地", "储藏室" },
	sections = {
		{
			title = "概述",
			text = [=[库尔森的营地位于{link:rebel-camp}反抗军营地{/link}以东的北部山丘中。它是士兵建造的，一看便知。它的围栏、塔楼和补给堆都布置得井井有条，唯一的一座两层房屋曾是上校的军需官的办公室。如今占据这里的是丛林战士、药师和突击队员。营地后方有一个通向山丘深处的洞穴。上校的手下称之为储藏室，{link:colonel-kurzen}库尔森上校{/link}本人就在洞穴深处发号施令。]=],
		},
	},
})

Translate("zhCN", "grom-gol-base-camp", {
	title = "格罗姆高营地",
	aliases = { "格罗姆高" },
	sections = {
		{
			title = "概述",
			text = [=[格罗姆高营地是大酋长在{link:stranglethorn-vale}荆棘谷{/link}西岸的前哨。{link:horde}部落{/link}来到丛林，并不是为了与这里的部族开战。它来这里，是为了保持一条通往{link:stonard}斯通纳德{/link}的补给线畅通，斯通纳德是它在东北方{link:swamp-of-sorrows}沼泽{/link}中的要塞。但迅猛龙在道路上猎食，{link:ogres}食人魔{/link}伏击商队，营地每多存在一天都要为之而战。飞艇从营地的塔楼升起，飞往{link:orgrimmar}奥格瑞玛{/link}和{link:undercity}幽暗城{/link}。{link:darkspear-trolls}暗矛{/link}使者也在这里工作，执行着他们自己的使命。]=],
		},
	},
})

Translate("zhCN", "ruins-of-zul-kunda", {
	title = "祖昆达废墟",
	aliases = { "祖昆达" },
	sections = {
		{
			title = "概述",
			text = [=[祖昆达废墟矗立在丛林的西北海岸，那里曾有一座{link:trolls}巨魔{/link}城市眺望着大海。如今占据这里的是血顶部族。他们的酋长{link:gan-zulah}甘祖拉恩{/link}和他的巫医{link:nezzliok-the-dire}可怕的奈兹里奥克{/link}住在废墟深处，他们的猎头者沿着海岸一路游荡到祖丹亚废墟。两块刻有古老巨魔传说的石板仍然立在断壁残垣之间。前来抄录它们的人很少久留。]=],
		},
	},
})

Translate("zhCN", "ruins-of-zul-mamwe", {
	title = "祖玛维废墟",
	aliases = { "祖玛维" },
	sections = {
		{
			title = "概述",
			text = [=[在丛林中部，{link:gurubashi-arena}古拉巴什竞技场{/link}以东，是劈颅部族的土地。他们的村落坐落在巴里亚曼、赞塔加和祖玛维的废墟中，每个村落都保存着一堆从敌人那里取来的战利品头骨。劈颅{link:trolls}巨魔{/link}与北方的血顶巨魔交战，也与对{link:darkspear-trolls}暗矛{/link}的记忆交战。他们的酋长是残忍的安纳塞克，他们的巫医莫格被称为不死者。他们的獠牙又大又好，一些地精为它们找到了一种用途，而那些购买虎牙的买家是不会喜欢的。]=],
		},
	},
})

Translate("zhCN", "mizjah-ruins", {
	title = "米扎废墟",
	sections = {
		{
			title = "概述",
			text = [=[米扎废墟位于{link:grom-gol-base-camp}格罗姆高{/link}东南，隔着河流。它曾是一座{link:trolls}巨魔{/link}城镇。如今一伙{link:ogres}食人魔{/link}占据了这里，他们从城墙上扑向{link:horde}部落{/link}在丛林道路上的补给商队。格罗姆高的警告无人理会，营地的指挥官已经失去了耐心。在废墟的河对岸，黑豹和母虎潜行于灌木丛中。]=],
		},
	},
})

Translate("zhCN", "mosh-ogg-ogre-mound", {
	title = "莫什奥格食人魔山",
	aliases = { "莫什奥格", "莫什奥格食人魔" },
	sections = {
		{
			title = "概述",
			text = [=[莫什奥格食人魔山位于{link:stranglethorn-vale}荆棘谷{/link}东部的山区，在{link:zul-gurub}祖尔格拉布{/link}以南不远处。这是莫什奥格氏族{link:ogres}食人魔{/link}的要塞：其中有重殴者、战争贩子、萨满祭司和领主。食人魔法师{link:mai-zoth}麦佐斯{/link}曾住在深处，他从{link:darkspear-trolls}暗矛{/link}仍居住在丛林中的年代起就熟知这片丛林。莫什奥格还喜欢赌博，而且他们不喜欢输。一个曾从他们那里赢得太多的{link:humans}人类{/link}，带着他的赢利被赶出了土丘。]=],
		},
	},
})

Translate("zhCN", "lake-nazferiti", {
	title = "纳菲瑞提湖",
	aliases = { "纳菲瑞提", "风险投资公司营地" },
	sections = {
		{
			title = "概述",
			text = [=[纳菲瑞提湖位于丛林北部，{link:venture-company}风险投资公司{/link}在湖岸上建起了一座作业基地。它的伐木机砍伐森林，它的地质学家在山丘中挖掘奇异的蓝色水晶。工头考兹尔把他的图纸锁在自己的屋子里。风险投资公司在{link:stranglethorn-vale}荆棘谷{/link}没有朋友。{link:booty-bay}藏宝海湾{/link}的商人憎恨它，{link:the-baron}男爵{/link}派出了对付它的密探，而丛林本身似乎也在抵抗它。]=],
		},
	},
})

Translate("zhCN", "crystalvein-mine", {
	title = "水晶矿洞",
	sections = {
		{
			title = "概述",
			text = [=[水晶矿洞位于{link:grom-gol-base-camp}格罗姆高{/link}东南的山丘中。它的岩壁中藏着只有{link:stranglethorn-vale}荆棘谷{/link}才有的歌唱水晶，矿洞里挤满了蜥蜴。这些野兽吃水晶，水晶让它们的皮变得坚硬，因此一只被杀死的蜥蜴所产出的碎片，可以与从岩石中挖出的任何碎片一样精良。{link:venture-company}风险投资公司{/link}因为蜥蜴而进不了矿洞，于是改为在周围的山丘中挖掘水晶。据说，这些碎片会向那些能听见它们的人歌唱。]=],
		},
	},
})

Translate("zhCN", "the-vile-reef", {
	title = "暗礁海",
	aliases = { "暗礁" },
	sections = {
		{
			title = "概述",
			text = [=[暗礁海位于野人海岸的水下，在{link:grom-gol-base-camp}格罗姆高{/link}西北。很久以前，一场剧烈的大地震动让一座{link:trolls}巨魔{/link}城市沉没于此，它的街道如今躺在海底。巨魔给这个地方起了这个名字，因为{link:murlocs}鱼人{/link}在沉没的废墟中安了家，攻击所有靠近的人。废墟中立着一块石板，讲述着巨魔传说中的英雄格里{link:farmer-ray}雷{/link}克的故事。{link:darkspear-trolls}暗矛{/link}视这个故事为神圣。]=],
		},
	},
})

Translate("zhCN", "nek-mani-wellspring", {
	title = "纳克迈尼圣泉",
	aliases = { "圣泉" },
	sections = {
		{
			title = "概述",
			text = [=[在西海岸高高的悬崖上，{link:gurubashi-arena}古拉巴什竞技场{/link}以南，有一眼被学者称为神圣的泉水。没有人能就它属于谁达成一致。萨满们说，{link:azeroth}艾泽拉斯{/link}的每一个种族都声称它的泉水只为本族而受祝福，牧师和神秘主义者为此争论了不知多少年。如今一支{link:naga}纳迦{/link}探险队从海中上来，占据了这眼泉水。纳迦想用它做什么，至今无人知晓。]=],
		},
	},
})

Translate("zhCN", "the-cape-of-stranglethorn", {
	title = "荆棘谷海角",
	aliases = { "荆棘海角" },
	sections = {
		{
			title = "概述",
			text = [=[荆棘谷海角是丛林的南端，陆地在两片海之间收窄，伸向{link:booty-bay}藏宝海湾{/link}。巨猿在港口以东的薄雾{link:stranglethorn-vale}山谷{/link}中游荡。在{link:fleet-master-seahorn}海角{/link}东岸的水晶海岸上，矗立着{link:ruins-of-aboraz-and-jubuwal}阿博拉兹{/link}和朱布瓦尔的废墟，{link:zanzil-the-outcast}流亡者赞吉尔{/link}在那里统领着他的追随者。在南部海角的一个隐秘洞穴里，住着一位与灵魂交谈的巫医。血帆海盗已在南边的{link:wild-shore}蛮荒海岸{/link}登陆。海角是荆棘谷最繁忙的角落，也是最危险的角落之一。]=],
		},
	},
})

Translate("zhCN", "ruins-of-aboraz-and-jubuwal", {
	title = "阿博拉兹和朱布瓦尔废墟",
	aliases = { "阿博拉兹废墟", "朱布瓦尔废墟", "阿博拉兹", "朱布瓦尔" },
	sections = {
		{
			title = "概述",
			text = [=[在{link:booty-bay}藏宝海湾{/link}东北的水晶海岸上，矗立着两座破败的{link:trolls}巨魔{/link}城镇：阿博拉兹和朱布瓦尔。它们是{link:zanzil-the-outcast}流亡者赞吉尔{/link}的领地，他是一个被自己部族驱逐的巫医。他的追随者靠他的混合药剂过活，对他从不质疑。死者也在这里行走。藏宝海湾的三个还不起债的赌徒，如今在这些废墟中游荡，受了诅咒，中了蛊惑。赞吉尔的奴仆中曾有一个年轻的{link:darkspear-trolls}暗矛巨魔{/link}，他是一位酋长失落的儿子。]=],
		},
	},
})

Translate("zhCN", "jaguero-isle", {
	title = "哈圭罗岛",
	sections = {
		{
			title = "概述",
			text = [=[哈圭罗岛位于{link:fleet-master-seahorn}海角{/link}东{link:southsea-pirates}南海{/link}岸之外。岛上荒蛮，丛林茂密，岛上的野兽都听命于一只名为穆克拉国王的巨猿。黑豹在岸边潜行。很少有水手在这里靠岸，而靠岸的人也找不到港湾。天气晴朗时，从岛上的海滩可以看见西北方的{link:wild-shore}蛮荒海岸{/link}，以及西南方海盗们的高大船只。一个俘虏也曾看见过它们，并将一封信投入了大海。]=],
		},
	},
})

Translate("zhCN", "wild-shore", {
	title = "蛮荒海岸",
	aliases = { "血帆营地", "赤红之雾" },
	sections = {
		{
			title = "概述",
			text = [=[蛮荒海岸是{link:stranglethorn-vale}荆棘谷{/link}最南端的海岸，在{link:booty-bay}藏宝海湾{/link}的悬崖之外。{red:bloodsail-buccaneers}血帆海盗{/red}在这里建起了一座营地，他们称之为南方指挥所。他们的三艘船停泊在岸外：{i}赤红之雾{/i}号、{i}断潮之池{/i}号和{i}少女的好运{/i}号。在{i}赤红之雾{/i}号的甲板之下，{link:fleet-master-firallon}舰队指挥官菲尔拉伦{/link}筹划着他对藏宝海湾的战争。对于不挂血帆旗帜的人来说，这片海岸绝非可留之地。]=],
		},
	},
})

Translate("zhCN", "green-hills-of-stranglethorn", {
	title = "荆棘谷的青山",
	found = "书页散落在丛林各处；巴尼尔·石罐在奈辛瓦里远征队营地收集它们",
	aliases = { "《荆棘谷的青山》" },
	sections = {
		{
			title = "概述",
			text = [=[{i}荆棘谷的青山{/i}是{link:hemet-nesingwary}赫米特·奈辛瓦里二世{/link}亲笔写下的丛林狩猎之书。他的同伴{link:barnil-stonepot}巴尼尔·石罐{/link}正在替他审读，这时一阵风把书页吹散到了整个{link:stranglethorn-vale}荆棘谷{/link}。这本书共有四章。第一章交代背景，并列出猎人的同伴们。第二章满是猛虎和黑豹的故事。第三章讲述{link:sir-s-j-erlgadin}厄尔加丁爵士{/link}和{link:ajeck-rouack}罗欧克女士{/link}用{link:dwarves}矮人{/link}火枪完成的第一次猎杀，并以悬念收尾。第四章是盛大的终章。巴尼尔希望看到它出现在世界各地的图书馆里。]=],
		},
	},
})

Translate("zhCN", "baron-revilgaz", {
	title = "大财主里维加兹",
	subtitle = "藏宝海湾之主",
	found = "藏宝海湾，港口对面那座酒馆的顶层",
	hint = "爬上俯瞰藏宝海湾港口的那座酒馆的顶层。",
	allegiance = "藏宝海湾 · 热砂港",
	aliases = { "里维加兹" },
	sections = {
		{
			title = "概述",
			text = [=[大财主里维加兹是{link:booty-bay}藏宝海湾{/link}的地精领主。他在酒馆的顶层俯视着港口、船只、贸易和这座港口的种种争执。他自己的人称他为这片海岸上最臭名昭著的海盗，认识他的人没有谁会怀疑这一点。他富有、骄傲，很难招惹。他还收藏{link:trolls}巨魔{/link}帝国的古老遗物，为了在架子上添上一件，他会耗费别人大量的时间。]=],
		},
		{
			title = "意义",
			text = [=[里维加兹就是{link:booty-bay}藏宝海湾{/link}的法律。血帆海盗知道，只要他还活着，他们就必须按照这座港口的规矩行事，他们愿意付出高昂的代价看到他死去。他的密探监视着{link:venture-company}风险投资公司{/link}，他的朋友中有{link:kirin-tor}肯瑞托{/link}的大法师，他的钱财一直延伸到{link:kalimdor}卡利姆多{/link}的赛场。]=],
		},
		{
			title = "事迹",
			text = [=[• 他统治着{link:booty-bay}藏宝海湾{/link}，让它对每一艘付钱的船开放。
• 他养着{link:kebok}科博克{/link}和{link:krazek}克拉兹克{/link}这样的密探，他们为他带来传闻，并悄悄解决他的麻烦。
• 他命令科博克去对付一个开始排挤贸易亲王手下大亨们的地精。
• 他资助地精赛车手{link:pozzik}普兹克{/link}，并为他去索取{link:venture-company}风险投资公司{/link}一种燃料调节器的图纸。
• 他以前曾与{link:dalaran}达拉然{/link}的大法师{link:archmage-ansirem-runeweaver}安斯雷姆·鲁因{/link}打过交道。]=],
		},
	},
	chapters = {
		{
			title = "潮汐之石",
			hint = "给男爵带去闹鬼小岛的消息，并追查到底。",
			text = [=[酒馆里的水手们谈起海岸外的一座小岛，那里有水{link:elements}元素{/link}和一个胡言乱语的地精鬼魂出没。{link:krazek}克拉兹克{/link}把这个故事转告上去，里维加兹想起了他曾读过的一个{link:trolls}巨魔{/link}传说：潮汐之石，一件会诅咒持有者、使其在这个世界中时隐时现的遗物。据说一个名叫加兹班的地精巫师找到了它。里维加兹不愿离开{link:booty-bay}藏宝海湾{/link}亲自去和那些乏味的法师交谈，于是他把元素的护腕送到了{link:dalaran}达拉然{/link}。{link:archmage-ansirem-runeweaver}安斯雷姆{/link}找到了诅咒的痕迹，以及一把能破除诅咒的巨魔匕首。潮汐之石如今在{link:the-baron}男爵{/link}的收藏中占据着荣耀的位置。]=],
		},
		{
			title = "赞助人的恩惠",
			hint = "为闪光平原的一位地精赛车手寻求男爵的帮助。",
			text = [=[{link:booty-bay}藏宝海湾{/link}曾答应给地精赛车手{link:pozzik}普兹克{/link}一个新的燃料调节器，却一直没有送到。{link:venture-company}风险投资公司{/link}在{link:lake-nazferiti}纳菲瑞提湖{/link}的伐木机使用了这种新设计，而他们的工头把图纸锁得严严实实。里维加兹想要复制这些图纸，既是为了普兹克，也是为了他自己的记录。他不喜欢他的赛车手以为自己的赞助人抛弃了他们。]=],
		},
	},
	mentions = {
		{ text = "闹鬼的小岛" },
		{ text = "潮汐之石" },
		{ text = "水{link:elements}元素{/link}" },
