		{ id = "archmage-ansirem-runeweaver", name = "大法师安斯雷姆·鲁因", note = "解读诅咒的法师" },
		{ id = "catelyn-the-blade", name = "利刃凯特琳", note = "把她的匕首借给了他的事业" },
		{ id = "fleet-master-seahorn", name = "舰队指挥官卡拉·海角", note = "守卫港口的舰队之主" },
