})

Translate("zhCN", "hemet-nesingwary", {
	title = "赫米特·奈辛瓦里二世",
	subtitle = "巨兽猎手",
	found = "奈辛瓦里二世远征队营地，在丛林北部",
	hint = "找到那位营地位于纳菲瑞提湖上游的矮人猎手。",
	allegiance = "奈辛瓦里二世远征队营地 · 联盟",
	aliases = { "奈辛瓦里二世", "小赫米特·奈辛瓦里二世", "奈辛瓦里二世大师", "赫米特" },
	sections = {
		{
			title = "概述",
			text = [=[赫米特·奈辛瓦里二世是一个{link:dwarves}矮人{/link}，一个猎人，也是一个讲述狩猎故事的人。他的同伴称他为{link:alliance}联盟{/link}著名的英雄，在拿起火枪从事狩猎消遣之前，他曾在{link:lordaeron}洛丹伦{/link}的战场上作战。他的足迹遍布世界各地。如今他带着一队猎人同伴来到{link:stranglethorn-vale}荆棘谷{/link}，而吸引他来到这里的，首先是一头野兽：白虎{link:king-bangalash}虎王邦加拉什{/link}。]=],
		},
		{
			title = "意义",
			text = [=[奈辛瓦里二世有名、富有，人脉广阔。就连{link:booty-bay}藏宝海湾{/link}的地精也会留心打听他在做什么。他为自己的本领而自豪，对任何能与之匹敌的人都很慷慨，无论对方属于哪个种族、打着哪面旗帜。他写下了自己在丛林中狩猎的故事，他的同伴们希望看到它被全世界的人阅读。]=],
		},
		{
			title = "事迹",
			text = [=[• 他与{link:barnil-stonepot}巴尼尔·石罐{/link}、{link:ajeck-rouack}艾耶克·罗欧克{/link}和{link:sir-s-j-erlgadin}埃尔加丁爵士{/link}一起在北方的河边扎营。
• 他用猎杀迅猛龙来考验新来者，而阿耶克用猛虎、厄尔加丁爵士用黑豹来评判他们。
• 他曾与{link:tauren}牛头人{/link}{red:}鲁恩·蛮鬃{/red}一同在{link:desolace}凄凉之地{/link}狩猎野兽，尽管两个种族之间有着古老的敌意，两人还是成了朋友。
• 在动身前往丛林之前，他从{link:the-shimmering-flats}闪光平原{/link}的一个地精那里订购了一箱特制弹药。
• 他写下了{i}{link:green-hills-of-stranglethorn}荆棘谷的青山{/link}{/i}，讲述他的狩猎故事。]=],
		},
	},
	chapters = {
		{
			title = "狩猎大师",
			hint = "在丛林的迅猛龙面前证明你自己。",
			text = [=[营地的猎人们不会和随便什么人分享篝火。赫米特直截了当地定下考验：先是迅猛龙，然后是更迅捷的品种，再然后是最难追踪的丛林潜猎者。最后的考验是一只名叫泰希斯的迅猛龙，赫米特本人从未杀死过她。带回她的爪子的人，会被封为迅猛龙狩猎大师。]=],
		},
		{
			title = "白虎",
			hint = "猎杀那头把奈辛瓦里二世带到荆棘谷的野兽。",
			text = [=[当{link:kindal-moonweaver}辛达尔{/link}、巴尔瑟拉和泰希斯都已倒下之后，赫米特道出了他前来的真相。他并不是为了它们才渡海而来。他是为了白虎{link:king-bangalash}虎王邦加拉什{/link}而来，那头老虎不止一次让他一瘸一拐地逃回营地。老虎被杀死后，赫米特为这位完成了他自己未能做到之事的猎人欢呼，并将其封为远征队的同伴。]=],
		},
		{
			title = "老朋友",
			hint = "给这位猎人带去远方朋友的礼物。",
			text = [=[礼物仍会越过大海送到营地。{link:the-shimmering-flats}闪光平原{/link}的一位地精商人寄来了赫米特很久以前就已付过钱的一箱弹药。{link:desolace}凄凉之地{/link}的一个{link:tauren}牛头人{/link}寄来了一只科多兽角，并附上再次一同狩猎的邀请。赫米特对这两件礼物都很高兴。眼下他身在丛林深处，但他没有忘记{link:centaurs}半人马{/link}的土地。]=],
		},
	},
	mentions = {
		{ text = "欢迎来到丛林" },
		{ text = "迅猛龙大师" },
		{ text = "迅猛龙大师" },
		{ text = "迅猛龙大师" },
		{ text = "迅猛龙大师" },
		{ text = "大型猎物猎手" },
		{ text = "赫米特·奈辛瓦里二世" },
		{ text = "在{link:stranglethorn-vale}荆棘谷{/link}狩猎" },
		{ text = "调查营地" },
		{ text = "{link:green-hills-of-stranglethorn}荆棘谷的青山{/link}" },
	},
