Translate("zhCN", "lieutenant-doren", {
	title = "多伦上尉",
	subtitle = "反抗军首领",
	found = "反抗军营地，在丛林的最北端",
	hint = "寻找那位在暮色森林来路附近率领反抗军的军官。",
	allegiance = "暴风王国 · 反抗军营地",
	aliases = { "多伦" },
	sections = {
		{
			title = "概述",
			text = [=[多伦上尉指挥着{link:stranglethorn-vale}荆棘谷{/link}的反抗军。他和他的士兵曾在{link:colonel-kurzen}库尔森上校{/link}麾下效力，并且对他忠心耿耿。后来上校变了。随着库尔森陷入残暴，他手下的忠诚变成了愤怒，多伦带领那些不愿再追随他的人建起了自己的营地。从那以后，他们一直在与自己从前的指挥官交战。]=],
		},
		{
			title = "意义",
			text = [=[多伦打的是一场他无法独自取胜的战争。{link:colonel-kurzen}库尔森{/link}是一位出色的战术家，他的手下比反抗军多出许多倍。反抗军靠地精的补给、偷来的药品和秘密生存。多伦必须守好这些秘密，因为一句话落入不该听到的耳朵，就可能把刀架在他的士兵的喉咙上。]=],
		},
		{
			title = "事迹",
			text = [=[• 他据守{link:rebel-camp}反抗军营地{/link}，抵御上校的军队。
• 他派{link:private-thorsen}列兵索尔森{/link}回到{link:colonel-kurzen}库尔森{/link}的手下中充当间谍。
• 他追查库尔森的军需官书呆子赫罗德的记录，想弄清索尔森的秘密是如何泄露的。
• 他在自己的营地中找出了叛徒。
• 他派一位勇士进入{link:kurzen-s-compound}储藏室{/link}，去直面上校本人。]=],
		},
		{
			title = "未载之事",
			text = [=[没有记录说明多伦的部队是如何来到{link:stranglethorn-vale}荆棘谷{/link}服役的，也没有记录反抗军何时与他们的上校决裂。]=],
		},
	},
	chapters = {
		{
			title = "营中的叛徒",
			hint = "帮助中尉查明是谁出卖了他的间谍。",
			text = [=[只有三个人知道{link:private-thorsen}索尔森{/link}的任务：多伦、{link:sergeant-yohwa}尤瓦中士{/link}和索尔森本人。然而{link:colonel-kurzen}库尔森{/link}的手下也知道了。在书呆子赫罗德的保险箱里，有一张沾满泥污的字条，上面列着索尔森的巡逻路线、他的朋友和他的习惯，落款只有一个字母。巡逻时间表说明了其余的一切。那一整周与索尔森一同站岗的人是列兵默尔。多伦曾认为他是个勇敢的士兵，有一颗忠诚的心。这个发现让他痛心，但更让他松了一口气。]=],
		},
		{
			title = "上校的陨落",
			hint = "把反抗军的希望带进储藏室。",
			text = [=[当上校的丛林战士被削弱、他的特种部队被击溃之后，多伦提出了最后也最艰难的任务。那位为反抗军而战的人要进入{link:kurzen-s-compound}储藏室{/link}，突破{link:colonel-kurzen}库尔森{/link}的守卫，直面上校和他的队长们。报告传来时，多伦几乎不敢相信。自反抗开始以来，他的士兵们第一次能够松一口气。]=],
		},
	},
	mentions = {
		{ text = "丛林中的秘密" },
		{ text = "庄家赫罗德" },
		{ text = "间谍现形！" },
		{ text = "巡逻时间表" },
		{ text = "向多伦报告" },
		{ text = "特种部队" },
		{ text = "{link:colonel-kurzen}库尔森上校{/link}" },
	},
	bonds = {
		{ id = "colonel-kurzen", name = "库尔森上校", note = "他从前的指挥官和敌人" },
		{ id = "sergeant-yohwa", name = "尤瓦中士", note = "他信任的中士" },
		{ id = "private-thorsen", name = "列兵索尔森", note = "他的间谍" },
		{ id = "brother-nimetz", name = "尼麦兹修士", note = "探寻库尔森堕落的原因" },
		{ id = "krazek", name = "克拉兹克", note = "为营地送来补给" },
	},
})

Translate("zhCN", "nimboya", {
	title = "尼姆布亚",
	subtitle = "暗矛使者",
	found = "格罗姆高营地",
	hint = "与格罗姆高那个寻找部族失落之子的暗矛巨魔交谈。",
	allegiance = "暗矛巨魔 · 部落",
	sections = {
		{
			title = "概述",
			text = [=[尼姆布亚是{link:darkspear-trolls}暗矛{/link}部族的{link:trolls}巨魔{/link}，从遥远的{link:orgrimmar}奥格瑞玛{/link}被派回{link:stranglethorn-vale}荆棘谷{/link}。他的任务十分沉重。按照他的族人的一项古老习俗，他的酋长最小的儿子{link:yenniku}耶尼库{/link}被交给了{link:zul-gurub}祖尔格拉布{/link}的古拉巴什巨魔。当暗矛离开丛林去追随{link:thrall}萨尔{/link}时，这个男孩被留在了后面，从此下落不明。尼姆布亚前来寻找他，无论生死。]=],
		},
		{
			title = "意义",
			text = [=[尼姆布亚在{link:darkspear-trolls}暗矛{/link}曾经称为家园的土地上代表着他们。部族通过他延续着最古老的仇怨，也履行着对{link:horde}部落{/link}最新的职责：寻找{link:yenniku}耶尼库{/link}，与血顶部族作战，惩罚背叛了大酋长的{link:witherbark-trolls}枯木巨魔{/link}，以及{link:vol-jin}沃金{/link}夺取宝剑{link:trol-kalar}托卡拉尔{/link}的计划。]=],
		},
		{
			title = "事迹",
			text = [=[• 他追猎血顶部族，打听{link:yenniku}耶尼库{/link}的消息。
• 他查验了许许多多的缩头，当男孩的头不在其中时，他心怀感激。
• 他用一口沸腾的大锅，从血顶酋长和他的巫医被砍下的头颅中逼出了真相。
• 他把自己的长矛送往北方的{link:the-hinterlands}辛特兰{/link}，作为给{link:witherbark-trolls}枯木巨魔{/link}的一个严厉警告。
• 他为{link:horde}部落{/link}的勇士们指明了通往{link:hammerfall}落锤镇{/link}和猎人{red:}赞古{/red}的道路。]=],
		},
	},
	chapters = {
		{
			title = "开口的头颅",
			hint = "把血顶酋长和他的巫医的头颅带到尼姆布亚的大锅前。",
			text = [=[尼姆布亚担心血顶部族杀死了那个男孩，他发誓，如果真是这样，就对他们的酋长施下六百年的诅咒。{link:gan-zulah}甘祖拉恩{/link}和{link:nezzliok-the-dire}奈兹里奥克{/link}的头颅被放进了他的大锅，死者开口了。即便到了那时，他们仍在讨价还价，要求得到战利品和鲜血才肯回答。最后，奈兹里奥克说出了真相。{link:yenniku}耶尼库{/link}还活着，但他已不再是他自己。巫医{link:zanzil-the-outcast}流亡者赞吉尔{/link}控制了他的身体和灵魂。]=],
		},
		{
			title = "拯救耶尼库",
			hint = "把暗矛失落的儿子带回家。",
			text = [=[此后希望变得十分渺茫，尼姆布亚说，就像最小的虫子一样渺小。但{link:kin-weelay}肯维雷{/link}从灵魂那里得知了心灵之眼的所在。它从{link:ogres}食人魔{/link}{link:mai-zoth}麦佐斯{/link}那里被夺走，巫医把它重新塑造成一颗能够容纳灵魂的宝石。借助它，{link:yenniku}耶尼库{/link}被击晕，他的灵魂从{link:zanzil-the-outcast}赞吉尔{/link}的掌控中被夺了回来，宝石被带到了{link:grom-gol-base-camp}格罗姆高{/link}。尼姆布亚曾以为他的使命毫无希望。他许诺部族将歌颂这一壮举，并把它刻在石头上。]=],
		},
	},
	mentions = {
		{ text = "寻找{link:yenniku}耶尼库{/link}" },
		{ text = "猎头" },
		{ text = "血顶部族的头颅" },
		{ text = "与{link:nezzliok-the-dire}奈兹里奥克{/link}交谈" },
		{ text = "与{link:gan-zulah}甘祖拉恩{/link}交谈" },
		{ text = "{link:yenniku}耶尼库{/link}的命运" },
		{ text = "拯救{link:yenniku}耶尼库{/link}" },
		{ text = "{link:trolls}巨魔{/link}克星" },
		{ text = "严厉的警告" },
	},
	bonds = {
		{ id = "yenniku", name = "耶尼库", note = "他寻找的酋长之子" },
		{ id = "kin-weelay", name = "肯维雷", note = "他的使者同伴" },
		{ id = "gan-zulah", name = "甘祖拉恩", note = "被他诅咒" },
		{ id = "nezzliok-the-dire", name = "可怕的奈兹里奥克", note = "在大锅中开口" },
		{ id = "zanzil-the-outcast", name = "流亡者赞吉尔", note = "控制了耶尼库" },
		{ id = "zengu", name = "森古", note = "被派去寻找托卡拉尔的猎人" },
		{ id = "vol-jin", name = "沃金", note = "向他下达命令" },
	},
})

Translate("zhCN", "zanzil-the-outcast", {
	title = "流亡者赞吉尔",
	subtitle = "被流放的巫医",
	found = "阿博拉兹废墟，在水晶海岸上",
	hint = "在藏宝海湾东北的废墟中寻找那个被放逐的巫医。",
	allegiance = "他自己的追随者",
	aliases = { "赞吉尔" },
	sections = {
		{
			title = "概述",
			text = [=[赞吉尔是一个被自己部族驱逐的{link:trolls}巨魔{/link}巫医。他的首领们畏惧他，这并非没有道理。他懂得如何扭曲他人的心智。他用丛林中的植物熬制一种混合药剂，能让饮用者意志迟钝、身体强壮，他在{link:ruins-of-aboraz-and-jubuwal}阿博拉兹和朱布瓦尔废墟{/link}中的追随者就靠它过活。在那里游荡的死者，或许也是拜他所赐才落得如此境地。]=],
		},
		{
			title = "意义",
			text = [=[赞吉尔的技艺已传播到了丛林之外。{link:booty-bay}藏宝海湾{/link}的地精购买他的混合药剂样品，其中一个还学会了把它酿成一种{link:brewnall-village}烈酒{/link}，用于他自己的图谋。在遥远的北方，{link:si-7}军情七处{/link}的密探得知，赞吉尔的{link:trolls}巨魔{/link}懂得用毒药让死者复生，而这个秘密已落入{link:defias-brotherhood}迪菲亚潜行者{/link}手中。在{link:tarren-mill}塔伦米尔{/link}，{link:serge-hinott}瑟尔格·希诺特{/link}研究过他的毒药所带来的疯狂。]=],
		},
		{
			title = "事迹",
			text = [=[• 他因为能操控他人心智而被部族流放。
• 他在{link:ruins-of-aboraz-and-jubuwal}阿博拉兹{/link}和朱布瓦尔的废墟中率领着他的追随者。
• 他夺走了{link:darkspear-trolls}暗矛{/link}男孩{link:yenniku}耶尼库{/link}，控制了他的身体和灵魂。
• 据说他的药剂能让死者复生。]=],
		},
	},
	chapters = {
		{
			title = "混合药剂",
			hint = "从赞吉尔的追随者那里夺取束缚他们的药剂。",
			text = [=[{link:crank-fizzlebub}克兰克·菲兹巴布{/link}向愿意听的人把事情讲得明明白白。一种能压制意志、强化身体的混合药剂，对那些想要统治他人的人来说价值连城。他为此出了好价钱，还为保密多付了一点。]=],
		},
		{
			title = "被盗的灵魂",
			hint = "把暗矛少年从巫医的掌控中解救出来。",
			text = [=[赞吉尔对{link:yenniku}耶尼库{/link}的控制非常牢固，只有最强大的魔法才能打破。{link:darkspear-trolls}暗矛{/link}的巫医们用一个{link:ogres}食人魔{/link}的宝石制成了这种魔法。当灵魂宝石包裹住耶尼库的灵魂时，赞吉尔失去了他最珍贵的奴仆。]=],
		},
	},
	mentions = {
		{ text = "赞吉尔的秘密" },
		{ text = "{link:yenniku}耶尼库{/link}的命运" },
		{ text = "拯救{link:yenniku}耶尼库{/link}" },
		{ text = "回到{link:booty-bay}藏宝海湾{/link}" },
		{ text = "赞吉尔的混合药剂和傻瓜{link:brewnall-village}烈酒{/link}" },
		{ text = "巫毒债务" },
		{ text = "克拉文之塔" },
	},
	bonds = {
		{ id = "yenniku", name = "耶尼库", note = "他的奴仆" },
		{ id = "crank-fizzlebub", name = "克兰克·菲兹巴布", note = "购买他的混合药剂" },
		{ id = "nimboya", name = "尼姆布亚", note = "想从他手中夺走耶尼库" },
		{ id = "agent-kearnen", name = "密探吉尔妮", note = "揭开了毒药的线索" },
		{ id = "serge-hinott", name = "瑟尔格·希诺特", note = "解他的毒" },
	},
})

Translate("zhCN", "fleet-master-seahorn", {
