		{ id = "baron-revilgaz", name = "大财主里维加兹", note = "他的母港之主" },
	},
})

Translate("zhCN", "fleet-master-firallon", {
	title = "舰队指挥官菲尔拉伦",
	subtitle = "血帆海盗的舰队指挥官",
	found = "蛮荒海岸外，赤红之雾号的甲板之下",
	hint = "到停泊在蛮荒海岸外的赤红之雾号上寻找那位海盗船长。",
	allegiance = "血帆海盗",
	aliases = { "费拉伦" },
	sections = {
		{
			title = "概述",
